// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address owner;

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new PoCGame(address(this), 0);
        vm.stopPrank();
        owner = __invmut_eoa;
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        vm.prank(owner, owner);
        c.OpenToThePublic();

        vm.deal(actor, 1 ether);
        vm.startPrank(actor, actor);
        bool ok;
        try c.wager{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        assertTrue(ok, "any real-person actor can wager after OpenToThePublic");
    }
}
